import { CommonModule } from '@angular/common';
import { Component, computed, inject, OnInit, signal } from '@angular/core';
import {
  IonBackButton,
  IonButtons,
  IonContent,
  IonHeader,
  IonItem,
  IonLabel,
  IonList,
  IonListHeader,
  IonNote,
  IonSelect,
  IonSelectOption,
  IonTitle,
  IonToolbar,
} from '@ionic/angular/standalone';
import { Tag } from '../common/verse/verse';
import { WidgetSyncService } from '../common/widget/widget-sync.service';
import { FavoritesService } from '../favorites/favorites.service';
import { TagsService } from '../tags/tags.service';
import { LoggingService } from '../common/logging/logging.service';

@Component({
  selector: 'app-settings',
  templateUrl: './settings.page.html',
  styleUrls: ['./settings.page.scss'],
  imports: [
    CommonModule,
    IonBackButton,
    IonButtons,
    IonContent,
    IonHeader,
    IonItem,
    IonLabel,
    IonList,
    IonListHeader,
    IonNote,
    IonSelect,
    IonSelectOption,
    IonTitle,
    IonToolbar,
  ],
})
export class SettingsPage implements OnInit {
  private widgetSyncService = inject(WidgetSyncService);
  private favoritesService = inject(FavoritesService);
  private tagsService = inject(TagsService);
  private logger = inject(LoggingService);

  selectedTagId = signal<number | null>(null);
  refreshIntervalHours = signal<number>(12);
  availableTags = signal<Tag[]>([]);
  isLoading = signal(true);
  hasError = signal(false);

  refreshIntervalLabel = computed(() => {
    const hours = this.refreshIntervalHours();
    return hours === 1 ? 'every hour' : `every ${hours} hours`;
  });

  async ngOnInit() {
    try {
      // Load settings and tags in parallel for better performance
      await Promise.all([this.loadSettings(), this.loadTags()]);
      // Always sync favorites on page load to ensure widget is up to date
      await this.syncFavorites();
    } catch (error) {
      this.logger.error('[Settings] Error loading settings:', error);
      this.hasError.set(true);
    } finally {
      this.isLoading.set(false);
    }
  }

  private async loadSettings() {
    try {
      const settings = await this.widgetSyncService.getWidgetSettings();
      this.logger.log('[Settings] Loaded settings:', settings);
      // Default to null (All Favorites) if no tag is selected
      this.selectedTagId.set(settings.selectedTagId ?? null);
      this.refreshIntervalHours.set(settings.refreshIntervalHours ?? 12);
    } catch (error) {
      this.logger.error('[Settings] Error loading settings:', error);
      // Default to All Favorites and 12 hours on error
      this.selectedTagId.set(null);
      this.refreshIntervalHours.set(12);
      throw error;
    }
  }

  private async loadTags() {
    try {
      const tags = await this.tagsService.getUserTags();
      this.logger.log('[Settings] Loaded tags for widget:', tags);
      this.availableTags.set(tags);
    } catch (error) {
      this.logger.error('[Settings] Error loading tags:', error);
      this.availableTags.set([]);
    }
  }

  async onTagSelectionChange(event: CustomEvent) {
    const tagId = event.detail.value as number | null;
    this.logger.log('[Settings] Tag selection changing to:', tagId);

    try {
      await this.widgetSyncService.setSelectedTag(tagId);
      this.selectedTagId.set(tagId);
      // Re-sync favorites when tag changes to update the widget
      await this.syncFavorites();
    } catch (error) {
      this.logger.error('[Settings] Error setting selected tag:', error);
    }
  }

  async onRefreshIntervalChange(event: CustomEvent) {
    const intervalHours = event.detail.value as number;
    this.logger.log('[Settings] Refresh interval changing to:', intervalHours, 'hours');

    try {
      await this.widgetSyncService.setRefreshInterval(intervalHours);
      this.refreshIntervalHours.set(intervalHours);
    } catch (error) {
      this.logger.error('[Settings] Error setting refresh interval:', error);
    }
  }

  private async syncFavorites() {
    try {
      const favorites = await this.favoritesService.getFavorites();
      this.logger.log('[Settings] Syncing', favorites.length, 'favorites to widget');
      await this.widgetSyncService.syncFavorites(favorites);
    } catch (error) {
      this.logger.error('[Settings] Error syncing favorites:', error);
    }
  }

  getTagColor(tag: Tag): string {
    return tag.color || '#6366f1';
  }
}

